"""Genera un anotador local para las sesiones de candidatos audiovisuals."""
from __future__ import annotations
import csv,json
from pathlib import Path
ROOT=Path(__file__).parents[1]; PROV=ROOT/'proveniencia'; OUT=PROV/'auditoria-sessions-candidats.html'
def read(p):
 with p.open(encoding='utf-8',newline='') as h:return list(csv.DictReader(h,delimiter='\t'))
def main():
 rows=[]
 for name in ['sessio-01.tsv','sessio-03.tsv','sessio-04.tsv']:
  for r in read(PROV/'sessions'/name):
   if not r['id_global'].startswith('candidate') and not r['id_global'].startswith('lead-'):continue
   x=dict(r);x['sessio']=name.replace('.tsv','');rows.append(x)
 payload=json.dumps(rows,ensure_ascii=False).replace('</','<\\/')
 doc=f'''<!doctype html><html lang="ca"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audició de candidats — corpus de parla andorrana</title><style>body{{font:16px system-ui,sans-serif;max-width:1100px;margin:2rem auto;padding:0 1rem;color:#222}}label{{display:block;margin:.5rem 0}}select,input,textarea,button{{font:inherit;padding:.4rem}}textarea{{width:100%;min-height:4rem}}audio{{width:100%;margin:1rem 0}}.meta{{background:#f3f3f3;padding:.8rem;border-radius:.4rem}}.warn{{background:#fff4ce;padding:.6rem;border-radius:.4rem}}.progress{{float:right;color:#666}}.grid{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:.6rem}}</style></head><body><h1>Audició de candidats <span class="progress" id="progress"></span></h1><p>{len(rows)} clips candidats de les sessions 01, 03 i 04. Les dades automàtiques només orienten l'escolta; les anotacions es guarden localment i s'exporten separades del corpus canònic.</p><div class="grid"><label>Sessió<select id="session"><option value="tots">totes</option><option>sessio-01</option><option>sessio-03</option><option>sessio-04</option></select></label><label>Persona<select id="person"><option value="tots">totes</option></select></label><label>Només pendents<select id="pending"><option value="sí">sí</option><option value="no">no</option></select></label></div><p><button id="prev">Anterior</button> <button id="next">Següent</button> <button id="download">Descarrega TSV</button></p><main id="app"></main><script>const items={payload};const key='maia-auditoria-candidats-v1';let notes=JSON.parse(localStorage.getItem(key)||'{{}}'),index=0,view=[];const app=document.querySelector('#app'),session=document.querySelector('#session'),person=document.querySelector('#person'),pending=document.querySelector('#pending');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));const people=[...new Set(items.map(x=>x.persona))].sort();for(const p of people)person.insertAdjacentHTML('beforeend',`<option>${{esc(p)}}</option>`);function refresh(){{view=items.filter(x=>(session.value==='tots'||x.sessio===session.value)&&(person.value==='tots'||x.persona===person.value)&&(pending.value==='no'||!notes[x.id_global]||!notes[x.id_global].decision||notes[x.id_global].decision==='pendent'));index=Math.min(index,Math.max(0,view.length-1));render()}}function render(){{if(!view.length){{app.innerHTML='<p>No hi ha clips amb aquests filtres.</p>';progress.textContent='0/0';return}}const x=view[index],n=notes[x.id_global]||{{}};progress.textContent=`${{index+1}}/${{view.length}}`;app.innerHTML=`<h2>${{esc(x.forma)}} · ${{esc(x.persona)}}</h2><div class="meta"><p><b>Sessió:</b> ${{esc(x.sessio)}} · <b>Clip:</b> <code>${{esc(x.clip)}}</code></p><p><b>Rol provisional:</b> ${{esc(x.rol_provisional)}} · <b>Motiu:</b> ${{esc(x.motiu_rol)}}</p><p><b>F0:</b> ${{esc(x.f0_median_hz)}} Hz · <b>F1/F2/F3:</b> ${{esc(x.f1_hz)}} / ${{esc(x.f2_hz)}} / ${{esc(x.f3_hz)}} Hz · <b>Pausa:</b> ${{esc(x.pausa_mediana_s)}} s</p><p><b>ASR small:</b> ${{esc(x.text_small)}}<br><b>ASR base:</b> ${{esc(x.text_base)}}<br><b>ASR greedy:</b> ${{esc(x.text)}}</p></div><audio controls preload="metadata" src="${{esc(x.clip)}}"></audio><p class="warn">Escolta el fragment. Confirma primer la veu i després la forma; no assumeixis que el text ASR sigui correcte.</p><label>Veu<select id="speaker"><option>pendent</option><option>persona-candidata</option><option>entrevistador</option><option>mixt</option><option>incerta</option></select></label><label>Decisió de la forma<select id="decision"><option>pendent</option><option>sí</option><option>no</option><option>incerta</option></select></label><label>Variant escoltada<input id="variant"></label><label>Trets fonètics<textarea id="phon"></textarea></label><label>Prosòdia / pauses<textarea id="pros"></textarea></label><label>Nota<textarea id="note"></textarea></label>`;for(const [id,k] of [['speaker','speaker'],['decision','decision'],['variant','variant'],['phon','phon'],['pros','pros'],['note','note']]){{const e=document.querySelector('#'+id);e.value=n[k]||'';e.addEventListener('input',()=>save(x))}}}}function save(x){{notes[x.id_global]={{speaker:document.querySelector('#speaker').value,decision:document.querySelector('#decision').value,variant:document.querySelector('#variant').value,phon:document.querySelector('#phon').value,pros:document.querySelector('#pros').value,note:document.querySelector('#note').value}};localStorage.setItem(key,JSON.stringify(notes));if(pending.value==='sí')refresh()}}prev.onclick=()=>{{index=Math.max(0,index-1);render()}};next.onclick=()=>{{index=Math.min(view.length-1,index+1);render()}};session.onchange=refresh;person.onchange=refresh;pending.onchange=refresh;download.onclick=()=>{{const h=['id_global','sessio','origen','persona','forma','clip','speaker','decision','variant','phon','pros','note'];const lines=[h.join('\\t')];for(const x of items){{const n=notes[x.id_global]||{{}};lines.push([x.id_global,x.sessio,x.origen,x.persona,x.forma,x.clip,n.speaker||'pendent',n.decision||'pendent',n.variant||'',n.phon||'',n.pros||'',n.note||''].map(v=>String(v).replace(/[\\t\\n]/g,' ')).join('\\t'))}}const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\\n')],{{type:'text/tab-separated-values'}}));a.download='anotacions-auditoria-candidats.tsv';a.click()}};const progress=document.querySelector('#progress'),prev=document.querySelector('#prev'),next=document.querySelector('#next'),download=document.querySelector('#download');refresh();</script></body></html>'''
 OUT.write_text(doc,encoding='utf-8');print(f'{len(rows)} clips candidats')
if __name__=='__main__':main()
